import{_ as a,o,c as r,a2 as l}from"./chunks/framework.DpbdyYUv.js";const i="/unit_devlab_esp32_examples/assets/alexavoz.mq0RaRlk.gif",g=JSON.parse('{"title":"Lab 8: PULSAR Powersupply — Zigbee + Integración con Alexa","description":"","frontmatter":{},"headers":[],"relativePath":"examples/labs08-zigbee-pulsar-powersupply.md","filePath":"examples/labs08-zigbee-pulsar-powersupply.md"}'),n={name:"examples/labs08-zigbee-pulsar-powersupply.md"};function t(d,e,s,c,p,u){return o(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="lab-8-pulsar-powersupply-—-zigbee-integracion-con-alexa" tabindex="-1">Lab 8: PULSAR Powersupply — Zigbee + Integración con Alexa <a class="header-anchor" href="#lab-8-pulsar-powersupply-—-zigbee-integracion-con-alexa" aria-label="Permalink to &quot;Lab 8: PULSAR Powersupply — Zigbee + Integración con Alexa&quot;">​</a></h1><p><strong>PULSAR Powersupply</strong> convierte una placa <strong>Pulsar C6</strong> en una fuente de voltaje controlada por voz. Sobre la salida Qwiic I²C se conecta un módulo <strong>HUSB238</strong> — un disparador (<em>trigger</em>) de USB-C Power Delivery — capaz de negociar distintos voltajes (5 V, 9 V, 12 V, 15 V, 18 V o 20 V) frente a un cargador USB-C compatible con PD.</p><p>El firmware ya viene compilado en un binario listo para cargar con <strong>Panel Loader</strong>, así que no se necesita instalar ningún entorno de desarrollo ni tocar una sola línea de código para completar esta práctica.</p><p>La integración se diseñó y probó con <strong>Alexa</strong> (un Echo con hub Zigbee integrado, como el Echo Dot Max): al unirse, el dispositivo aparece en la app de Alexa como una luz más — <code>Alexa, enciende la fuente</code> activa la salida en el último voltaje solicitado, y <code>Alexa, pon la fuente al 50%</code> reconfigura el voltaje según el nivel pedido, tal como si se tratara del brillo de un foco regulable.</p><h2 id="objetivo-del-taller" tabindex="-1">Objetivo del taller <a class="header-anchor" href="#objetivo-del-taller" aria-label="Permalink to &quot;Objetivo del taller&quot;">​</a></h2><p>Cargar el firmware <code>power_supply_zigbee</code> en una Pulsar C6 con un módulo HUSB238 conectado, emparejarla con Alexa y comprobar que el voltaje de salida se puede controlar por voz o desde la app.</p><h2 id="resultados-del-aprendizaje" tabindex="-1">Resultados del aprendizaje <a class="header-anchor" href="#resultados-del-aprendizaje" aria-label="Permalink to &quot;Resultados del aprendizaje&quot;">​</a></h2><p>Al finalizar, los participantes podrán:</p><ul><li>Explicar para qué sirve un módulo HUSB238 y qué es un contrato de Power Delivery (PD).</li><li>Conectar correctamente el HUSB238 a la Pulsar C6 mediante Qwiic.</li><li>Cargar el firmware <code>power_supply_zigbee</code> con Panel Loader.</li><li>Emparejar el dispositivo con Alexa y reconocerlo en la app como una luz regulable.</li><li>Controlar el voltaje de salida con comandos de voz o desde el control de brillo de la app de Alexa.</li><li>Entender por qué el porcentaje de brillo no representa &quot;más o menos energía&quot;, sino la selección de uno de los voltajes disponibles.</li><li>Resolver los problemas más comunes de emparejamiento.</li></ul><h2 id="materiales-para-el-taller" tabindex="-1">Materiales para el taller <a class="header-anchor" href="#materiales-para-el-taller" aria-label="Permalink to &quot;Materiales para el taller&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Producto</th><th>Cantidad</th><th>Función</th></tr></thead><tbody><tr><td>PULSAR C6 (ESP32-C6)</td><td>1</td><td>Ejecuta el firmware <code>power_supply_zigbee</code></td></tr><tr><td>Módulo HUSB238 (trigger USB-C PD)</td><td>1</td><td>Negocia el contrato de voltaje con el cargador</td></tr><tr><td>Cargador USB-C con Power Delivery</td><td>1</td><td>Debe anunciar al menos un perfil de los soportados (5/9/12/15/18/20 V)</td></tr><tr><td>Cable Qwiic (JST-SH 4 pines)</td><td>1</td><td>Conecta la Pulsar C6 con el HUSB238</td></tr><tr><td>Echo con hub Zigbee integrado (Echo Dot Max u otro modelo con hub Zigbee)</td><td>1 por red</td><td>Forma la red Zigbee y expone el dispositivo a Alexa</td></tr><tr><td>Cable USB de datos</td><td>1</td><td>Programación mediante Panel Loader</td></tr></tbody></table><h2 id="conexion-del-husb238" tabindex="-1">Conexión del HUSB238 <a class="header-anchor" href="#conexion-del-husb238" aria-label="Permalink to &quot;Conexión del HUSB238&quot;">​</a></h2><p>El HUSB238 se conecta directamente a la salida Qwiic de la Pulsar C6 con un cable Qwiic (4 pines: <code>SDA</code>, <code>SCL</code>, 3V3 y GND) — no requiere cableado manual ni soldadura. Conecta también el cargador USB-C con PD al puerto de entrada del HUSB238 <strong>antes de encender la placa</strong>, para que el firmware detecte al arrancar qué voltajes admite ese cargador.</p><h2 id="carga-de-firmware-—-panel-loader" tabindex="-1">Carga de firmware — Panel Loader <a class="header-anchor" href="#carga-de-firmware-—-panel-loader" aria-label="Permalink to &quot;Carga de firmware — Panel Loader&quot;">​</a></h2><p>Al igual que en el Lab 7, la Pulsar C6 se programa desde el navegador con <strong>Panel Loader</strong>, sin instalar <code>esptool</code> ni drivers adicionales.</p><p><strong><a href="https://unit-electronics-labs.github.io/unit_microsupport_labs/" target="_blank" rel="noreferrer">Abrir Panel Loader</a></strong></p><blockquote><p>Requiere un navegador con soporte WebSerial/WebUSB (Chrome o Edge de escritorio). Firefox y Safari no son compatibles.</p></blockquote><h3 id="descarga-de-firmware-merged" tabindex="-1">Descarga de firmware merged <a class="header-anchor" href="#descarga-de-firmware-merged" aria-label="Permalink to &quot;Descarga de firmware merged&quot;">​</a></h3><p>Este binario ya contiene las imágenes necesarias (bootloader, tabla de particiones y aplicación) en un solo archivo, listo para seleccionarse desde Panel Loader:</p><table tabindex="0"><thead><tr><th>Firmware</th><th>Aplicación</th><th>Archivo de descarga</th></tr></thead><tbody><tr><td>Power Supply</td><td>Para la Pulsar C6 con módulo HUSB238 por Qwiic</td><td><a href="/unit_devlab_esp32_examples/examples/firmware/power_supply_zigbee_merged.bin">Descargar <code>power_supply_zigbee_merged.bin</code></a></td></tr></tbody></table><h3 id="protocolo-de-carga" tabindex="-1">Protocolo de carga <a class="header-anchor" href="#protocolo-de-carga" aria-label="Permalink to &quot;Protocolo de carga&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Pestaña del panel</th><th>Protocolo</th><th>Placa de esta práctica</th></tr></thead><tbody><tr><td><strong>ESP32</strong></td><td>Serie / esptool-js</td><td>Pulsar C6 (ESP32-C6) con firmware Power Supply</td></tr></tbody></table><h3 id="pasos-para-cargar-el-firmware" tabindex="-1">Pasos para cargar el firmware <a class="header-anchor" href="#pasos-para-cargar-el-firmware" aria-label="Permalink to &quot;Pasos para cargar el firmware&quot;">​</a></h3><ol><li>Abre el enlace del Panel Loader y selecciona la pestaña <strong>ESP32</strong>.</li><li>En <strong>Firmware</strong>, da clic en <strong>Seleccionar firmware</strong> y elige el archivo <code>power_supply_zigbee_merged.bin</code> descargado.</li><li>Revisa la <strong>dirección de flash</strong> (<code>0x0000</code> por defecto) y la <strong>velocidad de carga</strong> (115200 baud es un valor seguro para empezar).</li><li>Da clic en <strong>Conectar ESP</strong> y selecciona el puerto que te ofrezca el navegador.</li><li>Da clic en <strong>Programar firmware</strong> y espera a que el progreso llegue a 100%.</li><li>Conecta el módulo HUSB238 por Qwiic y un cargador PD antes de encender la placa, para que detecte los voltajes disponibles al arrancar.</li></ol><h3 id="programacion-por-estaciones-varios-equipos-en-paralelo" tabindex="-1">Programación por estaciones (varios equipos en paralelo) <a class="header-anchor" href="#programacion-por-estaciones-varios-equipos-en-paralelo" aria-label="Permalink to &quot;Programación por estaciones (varios equipos en paralelo)&quot;">​</a></h3><p>En modo <strong>ESP32</strong> el panel ofrece una grilla de hasta <strong>10 estaciones</strong> para conectar y programar varias Pulsar C6 a la vez desde una sola computadora — útil si varias parejas programan su placa al mismo tiempo:</p><ol><li>Da clic en <strong>Conectar ESP</strong> dentro de cada estación para asignarle un dispositivo.</li><li>Usa <strong>Seleccionar conectados</strong> para marcar todas las estaciones con placa detectada.</li><li>Da clic en <strong>Programar seleccionados</strong> para cargar el mismo firmware en todas las estaciones marcadas en un solo paso.</li></ol><p>El resumen inferior (<strong>OK · SIN FLASH · ERROR</strong>) indica cuántas estaciones terminaron correctamente, y la consola <strong>esptool / ESP</strong> en la parte inferior del panel muestra el log en tiempo real — revísala si una carga falla o un dispositivo no queda en <strong>OK</strong>.</p><h2 id="emparejar-con-alexa" tabindex="-1">Emparejar con Alexa <a class="header-anchor" href="#emparejar-con-alexa" aria-label="Permalink to &quot;Emparejar con Alexa&quot;">​</a></h2><ol><li>Conecta el HUSB238 por Qwiic y un cargador PD antes de encender la placa, para que detecte los voltajes reales que ese cargador admite.</li><li>En la app de Alexa, inicia la búsqueda de dispositivos (<strong>Dispositivos → Agregar dispositivo → Zigbee</strong>, en un Echo con hub Zigbee integrado) <strong>antes</strong> de energizar o reiniciar la Pulsar C6.</li><li>Espera unos segundos a que la placa se una a la red y Alexa la detecte.</li><li>Confirma en la app que el dispositivo aparece como una luz regulable (fabricante <code>DevLab</code>, modelo <code>POWER_SUPPLY_PD</code>) y termina el registro si Alexa lo pide (por ejemplo, asignarle un nombre o una habitación).</li><li>Prueba por voz: <ul><li><code>Alexa, enciende [nombre del dispositivo]</code> → reactiva la salida en el último voltaje conocido.</li><li><code>Alexa, pon [nombre del dispositivo] al 100%</code> → selecciona el mayor voltaje que el cargador conectado admite.</li><li><code>Alexa, pon [nombre del dispositivo] al 50%</code> → selecciona un voltaje intermedio entre los que el cargador anuncia.</li><li><code>Alexa, apaga [nombre del dispositivo]</code> → marca la salida como apagada, sin desconectar físicamente el cargador.</li></ul></li></ol><p><img src="'+i+'" alt="Control por voz de la fuente con Alexa"></p><h2 id="usar-el-control-de-brillo-dimmer-en-la-app-de-alexa" tabindex="-1">Usar el control de brillo (dimmer) en la app de Alexa <a class="header-anchor" href="#usar-el-control-de-brillo-dimmer-en-la-app-de-alexa" aria-label="Permalink to &quot;Usar el control de brillo (dimmer) en la app de Alexa&quot;">​</a></h2><p>Además de los comandos de voz, el voltaje se puede ajustar tocando el control deslizante de brillo dentro de la app, igual que en cualquier foco regulable:</p><ol><li>Abre la app de Alexa y entra al dispositivo (<code>Dispositivos → [nombre del dispositivo]</code>).</li><li>Debajo del botón de encendido/apagado aparece un control deslizante de brillo — arrástralo para elegir el voltaje, o toca un porcentaje específico si la app lo permite.</li><li>Suelta el control: la app envía el nuevo nivel y el dispositivo selecciona el voltaje más cercano disponible (ver <a href="#prueba-de-funcionamiento">Prueba de funcionamiento</a>).</li></ol><blockquote><p>Si no ves el control deslizante, revisa que el dispositivo se haya emparejado como <strong>luz regulable</strong> y no como un simple enchufe/switch; vuelve a intentar el emparejamiento si Alexa lo registró como On/Off simple.</p></blockquote><h2 id="prueba-de-funcionamiento" tabindex="-1">Prueba de funcionamiento <a class="header-anchor" href="#prueba-de-funcionamiento" aria-label="Permalink to &quot;Prueba de funcionamiento&quot;">​</a></h2><ul><li>El porcentaje de brillo que muestra Alexa <strong>no</strong> es intensidad de luz: cada tramo corresponde a uno de los voltajes que el cargador conectado anuncia (por ejemplo, con un cargador que sólo admite 5 V y 9 V, 0–49% selecciona 5 V y 50–100% selecciona 9 V).</li><li>Si pides un porcentaje que no corresponde exactamente a un voltaje disponible, el dispositivo selecciona el más cercano que el cargador sí admite.</li><li><code>OFF</code> no desconecta el cargador ni corta el voltaje que ya se negoció: sólo marca la salida como apagada en Alexa. Para cambiar de voltaje de nuevo basta con pedir un nuevo porcentaje o volver a encenderlo.</li><li>Si cambias de cargador, reinicia la placa para que vuelva a detectar los voltajes que el nuevo cargador admite.</li></ul><h2 id="si-el-dispositivo-no-aparece-en-alexa" tabindex="-1">Si el dispositivo no aparece en Alexa <a class="header-anchor" href="#si-el-dispositivo-no-aparece-en-alexa" aria-label="Permalink to &quot;Si el dispositivo no aparece en Alexa&quot;">​</a></h2><ol><li>Verifica que el cargador PD esté conectado al HUSB238 <strong>antes</strong> de encender la Pulsar C6.</li><li>Cierra y vuelve a abrir la búsqueda de dispositivos Zigbee en la app de Alexa, y acerca la placa al Echo durante el emparejamiento.</li><li>Si la placa ya se emparejó antes con otra red o dejó de responder, vuelve a cargar el firmware desde Panel Loader (borra el emparejamiento anterior y la placa vuelve a intentar unirse desde cero).</li><li>Elimina el dispositivo desde la app de Alexa si quedó registrado como &quot;no disponible&quot; y repite el proceso de emparejamiento.</li></ol>',39)])])}const b=a(n,[["render",t]]);export{g as __pageData,b as default};
